def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me, last_opp = me[-1], opp[-1]

    opp_c = 0
    my_c = 0
    for i in range(n):
        if opp[i] == 'C':
            opp_c += 1
        if me[i] == 'C':
            my_c += 1

    opp_d = n - opp_c
    my_d = n - my_c

    if n == 1:
        return 'D' if last_opp == 'D' else 'C'

    if n == 99:
        return 'D'

    if opp_d == n:
        return 'D'

    r5_c = 0
    for o in opp[-5:]:
        if o == 'C':
            r5_c += 1

    opp_d_streak = 0
    for o in reversed(opp):
        if o == 'D':
            opp_d_streak += 1
        else:
            break

    dd_streak = 0
    for pair in reversed(history):
        if pair[0] == 'D' and pair[1] == 'D':
            dd_streak += 1
        else:
            break

    cd_streak = 0
    for pair in reversed(history):
        if pair[0] == 'C' and pair[1] == 'D':
            cd_streak += 1
        else:
            break

    if opp_c * 2 < n:
        return 'D'

    if n == 98:
        if last_opp == 'D' or last_me == 'D' or opp_d == 0:
            return 'D'
        return 'C'

    if last_opp == 'C':
        if opp_d == 0 and last_me == 'D':
            return 'D'

        if opp_d == 0 and my_d == 0:
            if n >= 20 and rng.random() < 0.02:
                return 'D'

        c_run = 0
        for o in reversed(opp):
            if o == 'C':
                c_run += 1
            else:
                break

        ended_d_streak = 0
        if c_run < n:
            idx = n - c_run - 1
            while idx >= 0 and opp[idx] == 'D':
                ended_d_streak += 1
                idx -= 1

        if ended_d_streak >= 2:
            if last_me == 'D' or opp_d <= 4 or opp_c * 5 >= 4 * n:
                return 'D'

        if last_me == 'D' and opp_d <= 4:
            return 'D'

        return 'C'

    if opp_d_streak == 1 and r5_c >= 3 and opp_c * 5 >= 3 * n:
        return 'C'

    if dd_streak >= 2 and opp_c * 5 >= 3 * n:
        return 'C'

    if opp_d_streak >= 4 and opp_c * 5 >= 3 * n and cd_streak <= 1:
        return 'C'

    return 'D'
